tool_args.command:
python3 -c "
import json, glob
for f in sorted(glob.glob('/root/symb_invariant_consensus/data/*.json')):
    try:
        with open(f) as fp:
            data = json.load(fp)
            if isinstance(data, list):
                print(f'{f}: {len(data)} items')
            elif isinstance(data, dict):
                print(f'{f}: dict with {len(data)} keys')
    except Exception as e:
        print(f'{f}: ERROR {e}')
"
